package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.kura.core.testutil.TestUtil;
import org.eclipse.kura.watchdog.WatchdogState;
import org.junit.After;
import org.junit.Test;

public class LateDeviceRefreshIntervalTest {

    private static final String WATCHDOG_DEVICE = "target/lateDeviceRefreshIntervalTestDevice";
    private static final String REBOOT_CAUSE_FILE = "target/lateDeviceRefreshIntervalRebootCause";
    private static final long SCHEDULING_TOLERANCE_MS = 5000;
    private static final long STATE_WAIT_TIMEOUT_MS = 10000;

    private final AtomicInteger availabilityChecks = new AtomicInteger();
    private int unavailableChecks;
    private int deviceTimeoutSeconds;
    private LateDeviceWatchdogServiceImpl svc;

    @Test
    public void refreshIntervalIsClampedWhenDeviceAppearsDuringGracePeriod() throws Exception {
        givenDeviceUnavailableAtConfigure();
        givenDeviceTimeoutSeconds(60);

        whenWatchdogServiceIsActivated(40000);
        whenDeviceAppearsOnNextTick();

        thenStateIs(WatchdogState.SUPERVISING);
        thenWatchdogIsRefreshedEvery(30000);
    }

    @Test
    public void refreshIntervalIsUnchangedWhenLateDeviceTimeoutAllowsPingInterval() throws Exception {
        givenDeviceUnavailableAtConfigure();
        givenDeviceTimeoutSeconds(60);

        whenWatchdogServiceIsActivated(20000);
        whenDeviceAppearsOnNextTick();

        thenStateIs(WatchdogState.SUPERVISING);
        thenWatchdogIsRefreshedEvery(20000);
    }

    @After
    public void cleanup() {
        if (this.svc != null) {
            this.svc.deactivate();
        }
        new File(REBOOT_CAUSE_FILE).delete();
    }

    private void givenDeviceUnavailableAtConfigure() {
        this.unavailableChecks = 1;
    }

    private void givenDeviceTimeoutSeconds(final int timeoutSeconds) {
        this.deviceTimeoutSeconds = timeoutSeconds;
    }

    private void whenWatchdogServiceIsActivated(final int pingInterval) throws Exception {
        this.svc = new LateDeviceWatchdogServiceImpl();
        this.svc.activate(getProperties(pingInterval));
        awaitPendingUpdate();
    }

    private void whenDeviceAppearsOnNextTick() throws Exception {
        final long deadline = System.currentTimeMillis() + STATE_WAIT_TIMEOUT_MS;
        while (this.svc.getWatchdogStatus().getState() != WatchdogState.SUPERVISING
                && System.currentTimeMillis() < deadline) {
            awaitPendingUpdate();
        }
        awaitPendingUpdate();
    }

    private void thenStateIs(final WatchdogState expectedState) {
        assertEquals(expectedState, this.svc.getWatchdogStatus().getState());
    }

    private void thenWatchdogIsRefreshedEvery(final long expectedIntervalMs) throws Exception {
        assertEquals(expectedIntervalMs, this.svc.getWatchdogStatus().getRefreshIntervalMs());

        final ScheduledFuture<?> pollTask = (ScheduledFuture<?>) TestUtil.getFieldValue(this.svc, "pollTask");
        final long nextRefreshDelay = pollTask.getDelay(TimeUnit.MILLISECONDS);
        assertTrue(nextRefreshDelay <= expectedIntervalMs);
        assertTrue(nextRefreshDelay > expectedIntervalMs - SCHEDULING_TOLERANCE_MS);
    }

    private Map<String, Object> getProperties(final int pingInterval) {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", true);
        properties.put("watchdogDevice", WATCHDOG_DEVICE);
        properties.put("watchdogMode", "direct");
        properties.put("pingInterval", pingInterval);
        properties.put("rebootCauseFilePath", REBOOT_CAUSE_FILE);
        properties.put("failOnUnavailableDevice", true);
        return properties;
    }

    private void awaitPendingUpdate() throws Exception {
        final ScheduledExecutorService pollExecutor = (ScheduledExecutorService) TestUtil.getFieldValue(this.svc,
                "pollExecutor");
        pollExecutor.submit(() -> {
        }).get(10, TimeUnit.SECONDS);
    }

    private class LateDeviceWatchdogServiceImpl extends HookedWatchdogServiceImpl {

        @Override
        protected WatchdogDevice createWatchdogDevice(final String watchdogDevice) {
            return new RecordingWatchdogDevice(LateDeviceRefreshIntervalTest.this.deviceTimeoutSeconds);
        }

        @Override
        protected boolean isWatchdogDeviceAvailable(final String watchdogDevice) {
            final LateDeviceRefreshIntervalTest test = LateDeviceRefreshIntervalTest.this;
            return test.availabilityChecks.incrementAndGet() > test.unavailableChecks;
        }
    }
}
